insert into public.recetas (id, data, created_at) values
('pimientos-asados', $receta${"id": "pimientos-asados", "name": "Pimientos asados", "cat": "Guarniciones", "servings": "", "time": "20 min + 10 de reposo", "photos": ["fotos/pimientos-asados-1.jpg"], "parts": [{"title": "", "ing": ["Pimientos de color grandes, para asar", "Aceite de oliva virgen extra", "Sal a gusto"], "steps": ["Cortar en mitades, limpiar y pintar con aceite de oliva (sal a gusto).", "Cocinar en la freidora de aire 20 minutos a 180°. Dejar reposar 10 minutos."]}], "tips": "", "wine": {"label": "Rosado", "note": "Acompaña bien el dulzor del pimiento asado.", "alt": ["Blanco joven"], "own": false}}$receta$::jsonb, now() - interval '0 minutes'),
('budin-de-banana', $receta${"id": "budin-de-banana", "name": "Budín de banana", "cat": "Dulces", "servings": "", "time": "", "photos": ["fotos/budin-de-banana-1.jpg"], "parts": [{"title": "", "ing": ["55 g de manteca", "200 g de azúcar", "1 huevo", "3 bananas pasadas (cuanto más negras/maduras, mejor)", "250 g de harina leudante", "1 cucharadita de sal", "Chips de chocolate"], "steps": ["Precalentar el horno a 180°. Enmantecar y enharinar un molde.", "Batir la manteca y el azúcar.", "Incorporar el huevo y pisar la banana, agregar la harina y la sal.", "Hornear por 1 hora."]}], "tips": "", "wine": {"label": "Café", "note": "Para la merienda. De sobremesa, un vino dulce.", "alt": ["Té negro", "Late harvest"], "own": false}}$receta$::jsonb, now() - interval '1 minutes'),
('pescado-a-la-crema', $receta${"id": "pescado-a-la-crema", "name": "Pescado a la crema", "cat": "Pescados", "servings": "", "time": "", "photos": ["fotos/pescado-a-la-crema-1.jpg", "fotos/pescado-a-la-crema-2.jpg"], "parts": [{"title": "", "ing": ["750 g de brótola, corvina, etc.", "2 cebollas", "2 morrones rojos", "500 g de papa", "Perejil", "300 ml de crema", "Pimienta negra"], "steps": ["Saltear a fuego lento la cebolla y los morrones cortados en tiras. Salpimentar.", "Mientras, salpimentar la crema de leche.", "Colocar en una fuente de vidrio armando un colchón, poner arriba el pescado y meter en el horno precalentado durante 20 min a unos 180°.", "Hacer las papas (hervidas o en microondas).", "Pasados los 20 min, retirar la fuente del horno, agregar las papas y la crema y dejar unos 5 min más.", "Retirar y tirar el perejil picado encima."]}], "tips": "", "wine": {"label": "Blanco · Chardonnay", "note": "Un blanco con algo de cuerpo acompaña la crema sin tapar al pescado.", "alt": ["Sauvignon Blanc"], "own": false}}$receta$::jsonb, now() - interval '2 minutes'),
('roll-de-pollo-hojaldrado', $receta${"id": "roll-de-pollo-hojaldrado", "name": "Roll de pollo hojaldrado", "cat": "Carnes", "servings": "4", "time": "35 min", "photos": ["fotos/roll-de-pollo-hojaldrado-1.jpg", "fotos/roll-de-pollo-hojaldrado-2.jpg"], "parts": [{"title": "", "ing": ["2 tapas pascualinas", "700 g de pechuga de pollo", "2 tomates perita", "150 g de queso mozzarella o similar", "200 g de queso crema"], "steps": ["Cocinar las pechugas de pollo.", "Dividir cada tapa pascualina en 2. Rellenar con queso crema, pollo, tomate cortado en cubos y queso mozzarella rallado, y envolver con la tapa.", "Dejar en el horno unos 25/30 min hasta que se cocine la masa."]}], "tips": "", "wine": {"label": "Blanco · Torrontés", "note": "Fresco y aromático, corta el queso crema.", "alt": ["Rosado"], "own": false}}$receta$::jsonb, now() - interval '3 minutes'),
('guiso-de-lentejas', $receta${"id": "guiso-de-lentejas", "name": "Guiso de lentejas", "cat": "Guisos", "servings": "4", "time": "", "photos": ["fotos/guiso-de-lentejas-1.jpg", "fotos/guiso-de-lentejas-2.jpg"], "parts": [{"title": "", "ing": ["1 chorizo colorado", "150 g de panceta ahumada", "250 g de roast beef u otra carne", "1 cebolla grande", "2 dientes de ajo", "1/2 morrón", "1 papa grande", "1 zanahoria", "2 tomates", "4 tomates secos", "350 g de lentejas", "1/2 vaso de puré de tomate", "Sal", "Pimienta", "Ajo en polvo", "Pimentón", "2 hojas de laurel", "Orégano", "Aceite de oliva", "Perejil", "Vino tinto 100 ml", "Agua caliente"], "steps": ["Cortar el chorizo colorado en rodajas. Ponerlo en una olla con agua y hervir durante 15 minutos: el chorizo se desgrasa y el guiso queda menos pesado.", "Cortar la panceta en pedacitos pequeños y la carne en cubos un poco más grandes.", "Picar la cebolla y el ajo finamente. El morrón, en cubitos chicos. Pelar las papas y las zanahorias y cortarlas en cubos y en rodajas, respectivamente.", "Picar los tomates y los tomates secos sin hidratar.", "Cocción: colocar los trocitos de panceta en una olla antiadherente a fuego fuerte. No tocar hasta que empiecen a hacer ruido de cocción; ahí revolver despacio y de vez en cuando. La idea es que quede bien crocante y no hervida.", "Cuando la panceta esté tostada, agregar el chorizo escurrido y cocinar a fuego fuerte hasta que se dore. Retirar todo de la olla sin limpiarla: queremos el fondo de cocción.", "Añadir la carne y dorarla igual que la panceta: no tocarla hasta que se dore de un lado y después moverla para dorar todos los lados. Retirarla y aprovechar otra vez el fondo de cocción.", "Agregar la cebolla, el morrón y el ajo con un poquito de sal para que larguen su agua. Cocinar hasta que la cebolla esté transparente.", "Sumar el tomate y cocinar unos 3 minutos sin dejar de revolver, hasta que tome un rojo más intenso.", "Añadir todas las carnes (chorizo, panceta y roast beef) y un chorro de vino (100 ml aprox.). Esperar a que se evapore.", "Agregar las papas, las zanahorias y los tomates secos mientras se revuelve. Condimentar con sal, pimienta, ajo en polvo, pimentón y una pizca de orégano. Por último, un vasito de puré de tomate. No escatimar en los condimentos: un guiso sin condimentar es insulso.", "Completar con las lentejas y el agua caliente. Agregar el laurel y revolver. Tapar y cocinar a fuego medio, abriendo cada tanto para revolver. Siempre tiene que haber agua caliente al ras de las lentejas.", "Una vez cocidas las lentejas, esperar a que se termine de evaporar el agua y dejar reposar."]}], "tips": "Si lo dejás reposar unas horas, el guiso gana sabor y queda mucho más sabroso.", "wine": {"label": "Tinto · Malbec", "note": "Acompaña el chorizo, la panceta y el pimentón. Si cocinaste con un tinto, servite el mismo.", "alt": ["Bonarda", "Cerveza roja"], "own": false}}$receta$::jsonb, now() - interval '4 minutes'),
('salsa-bolognesa', $receta${"id": "salsa-bolognesa", "name": "Salsa bolognesa", "cat": "Salsas", "servings": "4 abundantes", "time": "", "photos": ["fotos/salsa-bolognesa-1.jpg", "fotos/salsa-bolognesa-2.jpg"], "parts": [{"title": "", "ing": ["500 g de carne picada", "1 zanahoria grande", "1 cebolla grande", "1 diente de ajo", "Sal, pimienta blanca", "100 ml de vino blanco", "2 latas de tomate perita", "Una pizca de comino", "2 hojas de laurel"], "steps": ["Saltear el ajo, la cebolla y la zanahoria en una olla.", "Cuando la cebolla se transparente, agregar la carne picada hasta que cambie de color. Ahí agregar 100 ml de vino blanco a fuego medio hasta que se evapore el alcohol (se vaya el olor a alcohol).", "Agregar los tomates peritas picados y casi todo el jugo de las latas (reservar un poco por si la salsa se seca y hay que agregarle). Salpimentar y agregar el laurel y el comino (apenas una pizca, siempre menos de lo que uno cree).", "Cocinar a fuego medio/bajo durante 40 min. Si la salsa está muy líquida, con la olla destapada; si no, tapada para que no se seque."]}], "tips": "", "wine": {"label": "Tinto joven · Malbec", "note": "Con la pasta y la bolognesa, un tinto joven y frutado.", "alt": ["Sangiovese", "Bonarda"], "own": false}}$receta$::jsonb, now() - interval '5 minutes'),
('hamburguesas-cheese-bacon', $receta${"id": "hamburguesas-cheese-bacon", "name": "Hamburguesas dobles cheese bacon con papas", "cat": "Carnes", "servings": "", "time": "", "photos": ["fotos/hamburguesas-cheese-bacon-1.jpg"], "parts": [{"title": "", "ing": ["250 g de carne picada por hamburguesa (70% tapa de asado, 30% rosbif, doble picado)", "Pan de papa", "Cheddar", "Panceta ahumada", "Papas para freidora", "Sal, pimienta negra"], "steps": []}], "tips": "", "wine": {"label": "Cerveza IPA", "note": "El amargor limpia el cheddar y la panceta.", "alt": ["Malbec"], "own": false}}$receta$::jsonb, now() - interval '6 minutes'),
('risotto-de-hongos', $receta${"id": "risotto-de-hongos", "name": "Risotto de hongos portobellos", "cat": "Arroces", "servings": "", "time": "", "photos": ["fotos/risotto-de-hongos-1.jpg"], "parts": [{"title": "", "ing": ["1 taza de arroz carnaroli", "Hongos portobellos", "100 ml de vino blanco seco", "1 cucharada de manteca", "Aceite de oliva", "1 diente de ajo", "1 cebolla chica o media grande", "Caldo caliente", "Sal y pimienta blanca", "Queso rallado a gusto"], "steps": ["Picar finamente la cebolla y el ajo y saltear en un poco de aceite y manteca. Cocinar hasta que se transparenten.", "Agregar los hongos previamente lavados hasta que se doren un poco y larguen su agua.", "Agregar el arroz y mezclar; dejar que se tueste durante unos dos minutos.", "Verter el vino blanco y cocinar hasta que se evapore el alcohol. Salpimentar.", "Agregar caldo caliente de a poco y remover constantemente, a medida que el arroz absorbe el líquido (unos 18-20 minutos)."]}], "tips": "", "wine": {"label": "Blanco seco", "note": "El mismo blanco seco que usaste para cocinar.", "alt": ["Pinot Noir"], "own": false}}$receta$::jsonb, now() - interval '7 minutes'),
('spaghetti-puttanesca', $receta${"id": "spaghetti-puttanesca", "name": "Spaghetti a la puttanesca", "cat": "Pastas", "servings": "", "time": "", "photos": ["fotos/spaghetti-puttanesca-1.jpg"], "parts": [{"title": "", "ing": ["Spaghetti", "8-10 anchoas", "90 g de aceitunas verdes y negras", "Ajo", "Aceite de oliva", "500 g de tomate perita o cherry", "Perejil", "Orégano"], "steps": ["Saltear el ajo picado con las anchoas en aceite de oliva.", "Cuando el ajo se dore, agregar las aceitunas.", "Agregar los tomates cherry y luego un poco de vino y agua. Salpimentar y agregar orégano.", "Agregar aceite de oliva durante la cocción si hace falta.", "Agregar la pasta en la misma cacerola junto con el perejil picado. Mezclar la pasta con la salsa y servir."]}], "tips": "", "wine": {"label": "Tinto liviano · Pinot Noir", "note": "Poco tanino para no chocar con las anchoas y las aceitunas.", "alt": ["Rosado"], "own": false}}$receta$::jsonb, now() - interval '8 minutes'),
('salmon-con-eneldo', $receta${"id": "salmon-con-eneldo", "name": "Salmón con eneldo, mousse de zanahoria y papas rosti", "cat": "Pescados", "servings": "", "time": "", "photos": ["fotos/salmon-con-eneldo-1.jpg", "fotos/salmon-con-eneldo-2.jpg"], "parts": [{"title": "", "ing": ["Dos piezas de aprox. 350 g de salmón", "4 papas grandes", "125 g de queso provolone", "Eneldo", "2 zanahorias grandes", "Crema de leche", "Sal marina, pimienta, comino", "Rúcula y tomates cherry", "Aceite de oliva"], "steps": []}, {"title": "Papas rosti · 15/20 min", "ing": [], "steps": ["Rallar las papas crudas y colocarlas en un bowl. Rallar el queso provolone y mezclar con las papas.", "En una fuente de acero bien precalentada sobre el fuego, poner apenas unas gotas de aceite de oliva y la mezcla en puñados grandes. Aplastar hasta hacer un medallón de 1,5/2 cm de altura.", "Cocinar de un lado 8/10 min y luego del otro."]}, {"title": "Salmón rosado a la parrilla · 15/20 min", "ing": [], "steps": ["Colocar las piezas de salmón en una rejilla para pescado. Pintar con aceite de oliva para que no se peguen y salar con sal marina.", "Poner sobre la parrilla primero del lado de la piel, unos 10 min de cada lado. Servir sobre un colchón de mousse de zanahoria con hojas de eneldo encima."]}, {"title": "Mousse de zanahoria · 12 min", "ing": [], "steps": ["Pelar y cortar las zanahorias en rodajas y cocinarlas hervidas, o en el microondas unos 12 minutos en una fuente de vidrio cubierta con film. Conviene sumar un pedacito de papa para darle espesor.", "Pasar a un bowl con un chorrito de crema, sal, pimienta blanca y una pizca de comino (cuidado, que es muy invasivo). Procesar hasta que quede una mousse uniforme, que no sea líquida."]}], "tips": "", "wine": {"label": "Rosado bien frío", "note": "", "alt": ["Sauvignon Blanc"], "own": true}}$receta$::jsonb, now() - interval '9 minutes'),
('papatouille', $receta${"id": "papatouille", "name": "Papatouille", "cat": "Guarniciones", "servings": "", "time": "40 min", "photos": ["fotos/papatouille-1.jpg"], "parts": [{"title": "", "ing": ["Papas en rodajas", "Cebollas en rodajas", "Morrones en rodajas", "Ajo", "Aceite de oliva", "Orégano", "Otras especias"], "steps": ["Cortar las verduras en rodajas y colocarlas intercaladas en una fuente o asadera.", "Cocinar al horno unos 40 min, sin escatimar en aceite de oliva, hasta que queden doradas y cocidas."]}], "tips": "", "wine": {"label": "Según el plato principal", "note": "Elegilo por el plato que acompañe.", "alt": ["Tinto con carnes", "Blanco con pollo o pescado"], "own": false}}$receta$::jsonb, now() - interval '10 minutes'),
('menjunje-de-verduras', $receta${"id": "menjunje-de-verduras", "name": "Menjunje dulce de verduras", "cat": "Guarniciones", "servings": "", "time": "", "photos": ["fotos/menjunje-de-verduras-1.jpg"], "parts": [{"title": "", "ing": ["Ajo", "Morrón rojo y amarillo", "Cebolla", "Tomates cherry", "Aceite de oliva"], "steps": ["Calentar una fuente de acero en la parrilla.", "Poner aceite de oliva y colocar primero los morrones cortados en rectángulos y las cebollas en tiras, ni muy gruesas ni muy finas. Ir mezclando y revolviendo.", "Cuando los morrones estén un poco más blandos, agregar los ajos y los tomates cherry.", "Agregar aceite de oliva a criterio: el menjunje tiene que quedar oleoso.", "Cocinar hasta que los tomates cherry estén blandos."]}], "tips": "", "wine": {"label": "Tinto · Malbec", "note": "Pensado para acompañar carne a la parrilla.", "alt": ["Cabernet Sauvignon"], "own": false}}$receta$::jsonb, now() - interval '11 minutes'),
('bondiola-desmechada', $receta${"id": "bondiola-desmechada", "name": "Bondiola desmechada a la cacerola", "cat": "Carnes", "servings": "", "time": "", "photos": ["fotos/bondiola-desmechada-1.jpg"], "parts": [{"title": "", "ing": ["Aprox. 1,3 kg de bondiola", "Barbacoa", "Morrón rojo", "1 cebolla (blanca o morada)", "1 cebolla de verdeo o puerro", "1 zanahoria", "Ajo (3 dientes)", "Pimentón dulce, pimienta blanca, sal", "1 lata de cerveza negra (stout)", "1 caldo"], "steps": ["Cortar la bondiola en unos 3 trozos grandes si no entra entera. Bañarla en barbacoa y dejarla reposar.", "Cortar el morrón y las cebollas en tiras. La zanahoria, en medias rodajas. No hace falta picar el ajo muy chico.", "Precalentar una cacerola de al menos 24 cm de diámetro.", "Sellar todos los lados de la bondiola a fuego moderado a fuerte. Retirar y reservar.", "Sobre el fondo de olla, con apenas un poco de aceite, saltear las verduras. Cuando se ablanden un poco, volver a poner la bondiola. Salpimentar y agregar pimentón dulce. Bañar todo con la cerveza negra y un poco de caldo: el líquido tiene que tapar un 90% de la bondiola.", "Llevar a hervor y cocinar con la olla tapada 1,5 a 2 horas (según el tamaño), girando las piezas cada 30 minutos. Si pierde mucho líquido, agregar cerveza o caldo.", "Desarmar la bondiola con cuchara y tenedor. Conviene ponerle un poco más de barbacoa y mezclar bien."]}], "tips": "", "wine": {"label": "Cerveza negra (stout)", "note": "La misma de la cocción.", "alt": ["Malbec", "Syrah"], "own": false}}$receta$::jsonb, now() - interval '12 minutes'),
('papas-y-calabaza-verdeo', $receta${"id": "papas-y-calabaza-verdeo", "name": "Papas y calabaza a la crema de verdeo", "cat": "Guarniciones", "servings": "2", "time": "30 min", "photos": ["fotos/papas-y-calabaza-verdeo-1.jpg"], "parts": [{"title": "", "ing": ["300 g de papas", "300 g de calabaza (zapallo anco)", "1 cebolla de verdeo", "200 ml de crema de leche", "1 cucharada de maicena", "Sal y pimienta blanca"], "steps": ["Pelar y cortar las papas y la calabaza en cubos chicos. Cocinarlos de forma que se doren (aprox. 20 minutos a 190° en la freidora de aire, o en el horno).", "Saltear en manteca unos segundos la cebolla de verdeo y añadir la crema con la maicena ya mezclada. Sumar las papas y la calabaza doradas. Revolver cada tanto durante 2 minutos hasta que todo tome temperatura. Servir."]}], "tips": "", "wine": {"label": "Según el plato principal", "note": "Elegilo por el plato que acompañe.", "alt": ["Chardonnay con salmón"], "own": false}}$receta$::jsonb, now() - interval '13 minutes'),
('omelette-de-calabaza', $receta${"id": "omelette-de-calabaza", "name": "Omelette de calabaza asada, queso y tomates secos", "cat": "Huevos", "servings": "1", "time": "20 min", "photos": ["fotos/omelette-de-calabaza-1.jpg"], "parts": [{"title": "", "ing": ["4 huevos", "Calabaza", "100 g de queso en hebras a elección", "50 ml de leche", "Tomates secos rehidratados", "Sal y pimienta blanca"], "steps": ["Cortar la calabaza en cubos y asarla en el horno o la freidora de aire, hasta que quede blanda y apenas dorada.", "Batir los huevos y volcarlos en una sartén precalentada con un chorrito de leche. Agregar la calabaza y el queso en hebras (mejor uno blando).", "Agregar sal y pimienta a gusto.", "Cuando el huevo empiece a cocerse, plegar los laterales hacia el centro y seguir a fuego medio. Cuando la parte de abajo esté cocida, dar vuelta en la sartén para terminar la parte de arriba."]}], "tips": "", "wine": {"label": "Blanco · Sauvignon Blanc", "note": "Fresco, para un plato rápido y liviano.", "alt": ["Rosado"], "own": false}}$receta$::jsonb, now() - interval '14 minutes'),
('penne-parissiene', $receta${"id": "penne-parissiene", "name": "Penne rigate a la parissiene", "cat": "Pastas", "servings": "", "time": "30 min", "photos": ["fotos/penne-parissiene-1.jpg"], "parts": [{"title": "", "ing": ["50 g de harina", "50 g de manteca", "600 ml de leche", "200 ml de crema", "Nuez moscada", "Sal y pimienta blanca", "500 g de penne rigate", "Jamón", "Pollo", "Champiñones"], "steps": ["Preparar la salsa bechamel: en una sartén precalentada derretir la manteca y agregar la harina hasta formar una pasta. Sumar la leche de a poco, evitando saltos de temperatura, y mezclar con batidor para evitar grumos.", "Mezclar hasta lograr una consistencia uniforme. Agregar sal, pimienta blanca y nuez moscada a gusto.", "Poner una cucharada de manteca en una olla y, cuando se derrita, agregar el pollo en trozos, cubos o desmenuzado hasta que se dore. Luego los champiñones y el jamón en tiras. Se puede sumar algún diente de ajo picado.", "Agregar la crema y la salsa parissiene está lista.", "Cocinar los fideos de forma tradicional y volcarlos en la olla de la salsa para que se integren los sabores."]}], "tips": "", "wine": {"label": "Blanco · Chardonnay", "note": "Acompaña la bechamel y la crema.", "alt": ["Rosado"], "own": false}}$receta$::jsonb, now() - interval '15 minutes'),
('mayonesa-de-rucula', $receta${"id": "mayonesa-de-rucula", "name": "Mayonesa de rúcula", "cat": "Salsas", "servings": "", "time": "5 min", "photos": ["fotos/mayonesa-de-rucula-1.jpg"], "parts": [{"title": "", "ing": ["1 plantita de rúcula", "Mayonesa según necesidad (tipo Natura o Hellmann's, para evitar el huevo crudo)"], "steps": ["Poner en un bowl la rúcula y la mayonesa y procesar con minipimer."]}], "tips": "", "wine": {"label": "Según el plato", "note": "Es un acompañamiento: elegí el vino por el plato principal.", "alt": [], "own": false}}$receta$::jsonb, now() - interval '16 minutes'),
('noquis-con-hongos', $receta${"id": "noquis-con-hongos", "name": "Ñoquis con crema de hongos de pino y carne", "cat": "Pastas", "servings": "2", "time": "40 min", "photos": ["fotos/noquis-con-hongos-1.jpg"], "parts": [{"title": "", "ing": ["200 g de carne desmechada", "150 g de hongos de pino", "450 g de ñoquis de papa", "Sal y pimienta blanca", "200 ml de crema de leche", "Una cucharada de maicena", "1 diente de ajo", "100 ml de vino blanco"], "steps": ["Como los ñoquis se hacen muy rápido, conviene preparar la salsa con tiempo y tener el agua hirviendo lista para el final.", "Hidratar la maicena en un poco de leche aparte.", "Si los hongos están secos, hidratarlos en agua caliente (no hirviendo) unos 20 minutos. El caldo de hongos se puede reservar para otra cosa.", "Picar el diente de ajo y cortar los hongos en trozos más pequeños. La carne desmechada tiene que estar preparada de antes.", "Derretir una cucharadita de manteca y agregar el ajo. Apenas se dore un poco, sumar los hongos a fuego medio. Cuando se vayan ablandando, agregar la carne y un chorro de vino blanco para desglasar.", "Cuando se evapore el alcohol, agregar la crema y la leche con maicena. Salpimentar a gusto.", "Cocinar a fuego medio unos 4 minutos hasta que se integren los sabores."]}], "tips": "", "wine": {"label": "Tinto · Pinot Noir", "note": "Terroso como los hongos, sin tapar la crema.", "alt": ["Malbec liviano"], "own": false}}$receta$::jsonb, now() - interval '17 minutes'),
('spaghetti-al-wok', $receta${"id": "spaghetti-al-wok", "name": "Spaghetti salteado al wok con vegetales", "cat": "Pastas", "servings": "", "time": "40 min", "photos": ["fotos/spaghetti-al-wok-1.jpg"], "parts": [{"title": "", "ing": ["1/2 paquete de spaghetti", "Una bandeja de verdura para saltear al wok", "Salsa de soja", "Una cucharada de maicena", "Semillas de sésamo (opcional)"], "steps": ["Cocinar los spaghetti al dente en abundante agua hirviendo (aprox. 10 min).", "Mezclar la maicena con la salsa de soja.", "En un wok precalentado, saltear la verdura hasta que se vaya ablandando. No hace falta sal: la salsa de soja es muy salada.", "Cuando las verduras estén listas, agregar la pasta y la soja con maicena. Revolver hasta que todo tome color y algo de consistencia.", "Retirar, servir y agregar las semillas de sésamo."]}], "tips": "", "wine": {"label": "Blanco · Torrontés", "note": "Aromático, va bien con la soja.", "alt": ["Cerveza rubia"], "own": false}}$receta$::jsonb, now() - interval '18 minutes'),
('mac-and-cheese', $receta${"id": "mac-and-cheese", "name": "Mac & Cheese", "cat": "Pastas", "servings": "", "time": "30 min", "photos": ["fotos/mac-and-cheese-1.jpg"], "parts": [{"title": "", "ing": ["500 g de coditos", "400 g de cheddar", "175 g de mozzarella", "750 ml de leche", "65 g de harina", "65 g de manteca", "Pan rallado", "Sal, pimienta y pimentón dulce"], "steps": ["Cocinar la pasta al dente, 1 minuto menos de lo habitual, porque se sigue cocinando en el horno.", "En una olla o sartén derretir la manteca, agregar la harina y mezclar hasta que quede uniforme. Agregar la leche (a temperatura ambiente si es posible) de a poco, evitando grumos, hasta que tome consistencia.", "Agregar los quesos cortados hasta que se derritan por completo.", "Mezclar la pasta con la salsa y pasar todo a una fuente para horno. Poner queso rallado y un poco de pan rallado arriba para que quede crujiente.", "Llevar al horno a 200 °C hasta que se gratine la capa superior."]}], "tips": "", "wine": {"label": "Cerveza rubia", "note": "Refresca entre bocado y bocado de queso.", "alt": ["Chardonnay"], "own": false}}$receta$::jsonb, now() - interval '19 minutes'),
('mollejas-con-panceta', $receta${"id": "mollejas-con-panceta", "name": "Mollejas con crema de panceta y puré de papas", "cat": "Carnes", "servings": "3", "time": "50 min", "photos": ["fotos/mollejas-con-panceta-1.jpg"], "parts": [{"title": "", "ing": ["1 kg de mollejas, sin grasa ni membrana", "1 cebolla", "4 fetas gruesas de panceta ahumada", "Manteca", "Sal y pimienta negra", "200 ml de crema de leche", "Papas", "Leche"], "steps": ["Preparar antes el puré de papas, con papa, manteca y leche.", "Poner las mollejas limpias en una olla con agua fría. Llevar a hervor y dejar 10 minutos más.", "Retirar y cortar en rodajas de unos 1,5 cm.", "En una sartén o plancha precalentada, saltear la cebolla en manteca. Luego agregar la panceta y saltear hasta que esté crocante. Retirar.", "Sobre ese fondo, cocinar las mollejas hasta que queden crocantes de ambos lados.", "Agregar el salteado de cebolla y panceta, la crema, y salpimentar. Cocinar unos 3 minutos sin que se corte la crema."]}], "tips": "", "wine": {"label": "Blanco · Chardonnay con barrica", "note": "Con cuerpo para la crema y la panceta.", "alt": ["Pinot Noir"], "own": false}}$receta$::jsonb, now() - interval '20 minutes'),
('pollo-a-la-suiza', $receta${"id": "pollo-a-la-suiza", "name": "Pechuga de pollo a la suiza con papas españolas", "cat": "Carnes", "servings": "", "time": "50 min", "photos": ["fotos/pollo-a-la-suiza-1.jpg"], "parts": [{"title": "", "ing": ["2 pechugas de pollo", "500 ml de leche", "Harina o maicena", "50 g de manteca", "150 g de jamón cocido", "1 cebolla de verdeo", "Nuez moscada", "Sal", "500 g de papas"], "steps": []}, {"title": "Papas españolas · 40 min", "ing": [], "steps": ["Sin instrucciones. Nunca me salen bien. Buscar en internet."]}, {"title": "Salsa bechamel a la suiza · 25 min", "ing": [], "steps": ["Hidratar 2 cucharadas colmadas de maicena en 100 ml de leche.", "Derretir la manteca con 400 ml de leche en una sartén y agregar los 100 ml con maicena. Revolver a fuego lento hasta lograr la consistencia deseada.", "En otra sartén saltear brevemente la cebolla de verdeo y el jamón en tiras. Agregar a la salsa blanca con un poco de nuez moscada y sal.", "Revolver unos 3 min más hasta que se integren los sabores y colocar sobre las pechugas cocinadas."]}, {"title": "Pechugas de pollo · 10/25 min según el método", "ing": [], "steps": ["Abrir las pechugas en corazón para prepararlas como bifes. Se pueden hacer en sartén, plancha o freidora de aire."]}], "tips": "", "wine": {"label": "Blanco · Chardonnay", "note": "Acompaña la salsa blanca y el jamón.", "alt": ["Rosado"], "own": false}}$receta$::jsonb, now() - interval '21 minutes'),
('ensalada-rucula-lentejas', $receta${"id": "ensalada-rucula-lentejas", "name": "Ensalada de rúcula, cherry, calabaza asada, cebolla morada y lentejas", "cat": "Ensaladas", "servings": "", "time": "", "photos": ["fotos/ensalada-rucula-lentejas-1.jpg"], "parts": [{"title": "", "ing": ["Rúcula", "Tomates cherry", "Calabaza asada", "Cebolla morada", "Lentejas"], "steps": []}], "tips": "", "wine": {"label": "Blanco · Torrontés", "note": "Fresco para una ensalada con calabaza.", "alt": ["Rosado"], "own": false}}$receta$::jsonb, now() - interval '22 minutes'),
('ensalada-crudo-peras', $receta${"id": "ensalada-crudo-peras", "name": "Ensalada de rúcula, jamón crudo, peras y virutas", "cat": "Ensaladas", "servings": "", "time": "", "photos": ["fotos/ensalada-crudo-peras-1.jpg"], "parts": [{"title": "", "ing": ["Rúcula", "Jamón crudo", "Peras", "Virutas de queso"], "steps": []}], "tips": "", "wine": {"label": "Espumante brut", "note": "Las burbujas van bien con el crudo y la pera.", "alt": ["Rosado"], "own": false}}$receta$::jsonb, now() - interval '23 minutes'),
('picada-fresca', $receta${"id": "picada-fresca", "name": "Picada fresca", "cat": "Picadas", "servings": "", "time": "", "photos": ["fotos/picada-fresca-1.jpg", "fotos/picada-fresca-2.jpg"], "parts": [{"title": "", "ing": ["Morrones asados, mango, tomates cherry, uvas, salchichas copetín, jamón crudo serrano, quesos blandos y semiduros en láminas, salchichón primavera, leberwurst", "Peras envueltas en jamón crudo con roquefort amasado", "Papas fritas y talitas"], "steps": []}], "tips": "", "wine": {"label": "A elección", "note": "", "alt": ["Chardonnay", "Espumante brut"], "own": true}}$receta$::jsonb, now() - interval '24 minutes'),
('picada-mar-y-tierra', $receta${"id": "picada-mar-y-tierra", "name": "Picada de mar y tierra", "cat": "Picadas", "servings": "", "time": "", "photos": ["fotos/picada-mar-y-tierra-1.jpg"], "parts": [{"title": "", "ing": ["Tierra: espárragos gratinados con queso parmesano, canapés de palta con huevo, tomates cherry, rúcula, canapés de roquefort y morrón asado", "Mar: kanikama, canapés de caviar y queso crema, salmón rosado con Finlandia, brusquetas de rúcula, anchoas y morrones asados, brusquetas de roquefort y anchoas", "Galletitas Tosti y algunas papas fritas"], "steps": []}], "tips": "", "wine": {"label": "Blanco", "note": "", "alt": ["Sauvignon Blanc", "Espumante brut"], "own": true}}$receta$::jsonb, now() - interval '25 minutes'),
('berenjenas-roquefort-nueces', $receta${"id": "berenjenas-roquefort-nueces", "name": "Berenjenas con roquefort y nueces confitadas", "cat": "Picadas", "servings": "", "time": "", "photos": ["fotos/berenjenas-roquefort-nueces-1.jpg"], "parts": [{"title": "", "ing": ["Berenjenas", "Roquefort", "Nueces", "3 cucharadas de azúcar", "1 o 2 cucharadas de agua"], "steps": ["Cortar las berenjenas en rodajas de 1 cm y cocinarlas de ambos lados en el horno a 160 °C.", "En una sartén a fuego medio poner el azúcar y el agua. Cuando la mezcla empiece a cristalizar, agregar las nueces y mezclar casi constantemente unos minutos, hasta que el caramelo se vaya pegando a las nueces. Apagar el fuego y seguir mezclando hasta que se vean los cristales de azúcar.", "Poner roquefort sobre las rodajas y, sobre el roquefort, las nueces."]}], "tips": "", "wine": {"label": "Late harvest", "note": "Lo dulce del vino contra lo salado del roquefort.", "alt": ["Malbec"], "own": false}}$receta$::jsonb, now() - interval '26 minutes'),
('confitura-de-pimientos', $receta${"id": "confitura-de-pimientos", "name": "Confitura de pimientos rojos", "cat": "Salsas", "servings": "1 morrón = 1 frasco pequeño", "time": "45 min", "photos": ["fotos/confitura-de-pimientos-1.jpg", "fotos/confitura-de-pimientos-2.jpg"], "parts": [{"title": "", "ing": ["Morrón rojo", "150 g de azúcar", "1 cucharadita de limón"], "steps": ["Cortar el morrón en cubitos.", "Poner 1 cm de agua en una olla de buena superficie y agregar los morrones y el azúcar, a fuego muy bajo.", "Revolver cada 5 min para que no se queme ni se pegue el almíbar. Con el tiempo se reduce el agua y el morrón toma un rojo abrillantado.", "Después de unos 40 min se ve un hervor naranja/amarillento. Si al pasar una espátula por la olla está más viscoso que líquido, está listo.", "Unas gotas de limón evitan que quede demasiado dulce y realzan el sabor del morrón.", "Retirar los morrones con poco almíbar. El almíbar restante se puede guardar y usar aparte.", "Excelente con quesos como camembert o brie, o con carnes."]}], "tips": "", "wine": {"label": "Espumante brut", "note": "Con quesos como brie o camembert.", "alt": ["Rosado"], "own": false}}$receta$::jsonb, now() - interval '27 minutes'),
('salsa-de-ciboulette', $receta${"id": "salsa-de-ciboulette", "name": "Salsa de ciboulette", "cat": "Salsas", "servings": "", "time": "10 min", "photos": ["fotos/salsa-de-ciboulette-1.jpg"], "parts": [{"title": "", "ing": ["300 g de queso crema", "35 ml de leche", "Sal y pimienta blanca", "Ciboulette"], "steps": ["Cortar la ciboulette en trozos pequeños.", "Poner todo en un bowl, reservando algo de ciboulette para el final.", "Mezclar hasta que quede uniforme y decorar con ciboulette arriba."]}], "tips": "", "wine": {"label": "Según el plato", "note": "Es un acompañamiento: elegí el vino por el plato principal.", "alt": [], "own": false}}$receta$::jsonb, now() - interval '28 minutes')
